const reportInstances = `-- name: ReportInstances :many
update runners
set instance_seen_at = now(),
    instance_id = coalesce(runners.instance_id, reported.instance_id),
    instance_gone_at = null
from (
    select unnest($3::uuid[]) as runner_id, unnest($4::text[]) as instance_id
) as reported
where runners.id = reported.runner_id and runners.credential_id = $1
    and runners.region = $2
returning runners.id, runners.installation_id, runners.definition, runners.source, runners.cloud, runners.credential_id, runners.region, runners.spec, runners.labels, runners.attempt, runners.pool_id, runners.repository_id, runners.repository_full_name, runners.trigger_job_id, runners.name, runners.state, runners.finish_reason, runners.github_runner_id, runners.instance_id, runners.error, runners.lease_expires_at, runners.not_before, runners.created_at, runners.launching_at, runners.running_at, runners.busy_at, runners.finished_at, runners.instance_seen_at, runners.instance_gone_at, runners.terminate_requested_at, runners.deregistered_at, runners.provision_secret, runners.provisioned_at, runners.cache_token_hash, runners.cache_bucket
`

type ReportInstancesParams struct {
	CredentialID *uuid.UUID
	Region       string
	RunnerIds    []uuid.UUID
	InstanceIds  []string
}

// Records the instances the cloud lists for a (credential, region).
func (q *Queries) ReportInstances(ctx context.Context, arg ReportInstancesParams) ([]Runner, error) {
	rows, err := q.db.Query(ctx, reportInstances,
		arg.CredentialID,
		arg.Region,
		arg.RunnerIds,
		arg.InstanceIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Runner{}
	for rows.Next() {
		var i Runner
		if err := rows.Scan(
			&i.ID,
			&i.InstallationID,
			&i.Definition,
			&i.Source,
			&i.Cloud,
			&i.CredentialID,
			&i.Region,
			&i.Spec,
			&i.Labels,
			&i.Attempt,
			&i.PoolID,
			&i.RepositoryID,
			&i.RepositoryFullName,
			&i.TriggerJobID,
			&i.Name,
			&i.State,
			&i.FinishReason,
			&i.GithubRunnerID,
			&i.InstanceID,
			&i.Error,
			&i.LeaseExpiresAt,
			&i.NotBefore,
			&i.CreatedAt,
			&i.LaunchingAt,
			&i.RunningAt,
			&i.BusyAt,
			&i.FinishedAt,
			&i.InstanceSeenAt,
			&i.InstanceGoneAt,
			&i.TerminateRequestedAt,
			&i.DeregisteredAt,
			&i.ProvisionSecret,
			&i.ProvisionedAt,
			&i.CacheTokenHash,
			&i.CacheBucket,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reviveRunners = `-- name: ReviveRunners :many
with revived as (
    select runners.id, runners.trigger_job_id as old_trigger_job_id
    from runners
    where runners.id = any($1::uuid[])
        and runners.credential_id = $2
        and runners.state = 'finished'
        and runners.finish_reason = 'lease_expired'
        and runners.deregistered_at is null
    for update
)
update runners
set state = 'running', finish_reason = null, finished_at = null,
    trigger_job_id = null, instance_gone_at = null, running_at = coalesce(running_at, now())
from revived
where runners.id = revived.id
returning runners.id, revived.old_trigger_job_id
`

type ReviveRunnersParams struct {
	RunnerIds    []uuid.UUID
	CredentialID *uuid.UUID
}

type ReviveRunnersRow struct {
	ID              uuid.UUID
	OldTriggerJobID *int64
}

// A runner whose lease expired but whose instance the cloud now lists did
// launch, and may already be running a job, so it is revived rather than
// terminated, as long as GitHub still has it registered. It returns the
// job it was started for, so the retry runner queued for that job can be
// cancelled and the installation stays within max_runners.
func (q *Queries) ReviveRunners(ctx context.Context, arg ReviveRunnersParams) ([]ReviveRunnersRow, error) {
	rows, err := q.db.Query(ctx, reviveRunners, arg.RunnerIds, arg.CredentialID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReviveRunnersRow{}
	for rows.Next() {
		var i ReviveRunnersRow
		if err := rows.Scan(&i.ID, &i.OldTriggerJobID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

